function tabs(items,active,action){return `<div class="tabs" role="tablist" aria-label="${state.page} views">${items.map(s=>`<button role="tab" aria-selected="${s===active}" class="${s===active?'active':''}" onclick="${action}('${s}')">${s}</button>`).join('')}</div>`}
function changeTab(tab){state.tab=tab;render()}
function transactionRows(rows=txns){return rows.map(t=>`<div class="transaction-row"><div class="iconbox ${t.amount>0?'green':''}">${icon(t.type==='Loans'?'receipt':'wallet')}</div><div><h3>${t.label}</h3><small>${dateText(t.date)} · ${t.account}</small></div><span class="price ${t.amount>0?'positive':''}">${t.amount>0?'+':''}${money(t.amount)}</span></div>`).join('')}
function transactionTable(){const rows=txns.filter(t=>state.tab==='All activity'||t.type===state.tab);return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Transaction</th><th>Reference</th><th class="right">Amount</th><th>Status</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${dateText(t.date)}</td><td><b>${t.label}</b><span class="smalltext">${t.account}</span></td><td>${t.ref}</td><td class="right ${t.amount>0?'positive':''}">${t.amount>0?'+':''}${money(t.amount)}</td><td>${statusPill('Posted')}</td></tr>`).join('')}</tbody></table></div>`}
function goalCard(g){const percent=Math.min(100,Math.round(g.current/g.target*100));return `<div class="card"><div class="row"><div class="iconbox yellow">${icon('target')}</div>${statusPill(percent+'% saved')}</div><h3 style="margin-top:18px">${e(g.name)}</h3><div class="goal-progress" role="progressbar" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100" aria-label="${e(g.name)} progress"><span style="width:${percent}%"></span></div><p class="muted">${money(g.current)} of ${money(g.target)}</p><p class="smalltext">Target: ${dateText(g.date)}</p>${button('Update goal',`openGoal('${g.id}')`,'small')}</div>`}
